import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1786904142000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="my-private-gists-do-not-show-up" tabindex="-1">My private gists do not show up <a class="header-anchor" href="#my-private-gists-do-not-show-up" aria-label="Permalink to “My private gists do not show up”">​</a></h2><p>The token is missing the <code>gist:read</code> scope. The Opengist API does not reject a token without it — it silently returns only public gists, so everything private looks like it does not exist. Generate a new token with the scope and retry.</p><h2 id="every-call-fails-with-missing-required-environment-variable-s" tabindex="-1">Every call fails with &quot;missing required environment variable(s)&quot; <a class="header-anchor" href="#every-call-fails-with-missing-required-environment-variable-s" aria-label="Permalink to “Every call fails with &quot;missing required environment variable(s)&quot;”">​</a></h2><p>The server started without <code>OPENGIST_URL</code> or <code>OPENGIST_TOKEN</code>. That is a supported state — the tools stay listable — but no call can reach the API.</p><p>If you set them in a client config, check that they are inside the <code>env</code> object of <em>that server&#39;s</em> entry and that you restarted the client afterwards. Claude Desktop in particular only reads its config file at startup.</p><h2 id="the-server-exits-immediately-at-startup" tabindex="-1">The server exits immediately at startup <a class="header-anchor" href="#the-server-exits-immediately-at-startup" aria-label="Permalink to “The server exits immediately at startup”">​</a></h2><p>Only four things cause an exit: a malformed <code>OPENGIST_URL</code>, a protocol other than http/https, a URL containing a username or password, and an unwritable stdio transport. The reason is printed to stderr — in most clients that means the MCP log, not the chat window.</p><p>Missing credentials do <strong>not</strong> cause an exit.</p><h2 id="gist-content-is-untrusted-data-appears-on-every-response" tabindex="-1">&quot;Gist content is untrusted data&quot; appears on every response <a class="header-anchor" href="#gist-content-is-untrusted-data-appears-on-every-response" aria-label="Permalink to “&quot;Gist content is untrusted data&quot; appears on every response”">​</a></h2><p>That is the marker, not an error. Any response carrying text written by a person gets it. See <a href="/guide/security#untrusted-content">Security</a>.</p><h2 id="a-tool-refused-and-gave-me-a-confirmtoken" tabindex="-1">A tool refused and gave me a <code>confirmToken</code> <a class="header-anchor" href="#a-tool-refused-and-gave-me-a-confirmtoken" aria-label="Permalink to “A tool refused and gave me a confirmToken”">​</a></h2><p>Working as intended. Deleting, publishing and writing into a published gist all refuse their first call. Confirm with the user, then call again within five minutes with <code>confirmToken</code> set and every other argument unchanged.</p><p>If the second call is also refused, one of three things happened: more than five minutes passed, an argument changed between the calls (the token is bound to the exact effect), or the token was already used — they are single-use.</p><h2 id="a-file-came-back-as-contentomitted-binary" tabindex="-1">A file came back as <code>contentOmitted: &quot;binary&quot;</code> <a class="header-anchor" href="#a-file-came-back-as-contentomitted-binary" aria-label="Permalink to “A file came back as contentOmitted: &quot;binary&quot;”">​</a></h2><p>The content looked binary — a NUL byte, or a high share of control characters in the first 2 KB. Dumping it as text would fill the context with mojibake. Use the gist&#39;s <code>clone_url</code> and git if you need the actual bytes.</p><h2 id="search-gists-did-not-find-something-i-know-is-there" tabindex="-1"><code>search_gists</code> did not find something I know is there <a class="header-anchor" href="#search-gists-did-not-find-something-i-know-is-there" aria-label="Permalink to “search_gists did not find something I know is there”">​</a></h2><p>Three likely reasons:</p><ol><li><strong>It does not search file contents.</strong> Only titles, descriptions, topics and owners. Searching inside files would mean downloading every file of every gist.</li><li><strong>It was cut short.</strong> The result reports <code>scanned</code> and marks incomplete results explicitly — raise <code>maxPages</code> or narrow the <code>scope</code>.</li><li><strong>Wrong scope.</strong> It defaults to <code>mine</code>. Pass <code>scope: &quot;public&quot;</code> to search the whole instance.</li></ol><h2 id="the-links-in-results-point-at-localhost" tabindex="-1">The links in results point at localhost <a class="header-anchor" href="#the-links-in-results-point-at-localhost" aria-label="Permalink to “The links in results point at localhost”">​</a></h2><p>Opengist&#39;s own <code>external-url</code> (<code>OG_EXTERNAL_URL</code>) is not configured on the instance, so it reports <code>localhost</code> URLs. The gists are correct; only the links are wrong. Set it on the instance.</p><h2 id="can-i-use-it-against-a-self-signed-instance" tabindex="-1">Can I use it against a self-signed instance? <a class="header-anchor" href="#can-i-use-it-against-a-self-signed-instance" aria-label="Permalink to “Can I use it against a self-signed instance?”">​</a></h2><p>Yes: <code>OPENGIST_INSECURE_TLS=true</code>, which is scoped to the Opengist connection rather than the whole process. Installing the CA in the system trust store or setting <code>NODE_EXTRA_CA_CERTS</code> is better where possible — see <a href="/guide/configuration#tls">Configuration</a>.</p><h2 id="the-docker-container-exits-straight-away" tabindex="-1">The Docker container exits straight away <a class="header-anchor" href="#the-docker-container-exits-straight-away" aria-label="Permalink to “The Docker container exits straight away”">​</a></h2><p><code>docker run</code> needs <code>-i</code>. The transport is stdio, so without stdin the process has nothing to read and stops. Do not add <code>-t</code>: a TTY corrupts the protocol stream.</p><h2 id="can-i-stop-it-from-writing-at-all" tabindex="-1">Can I stop it from writing at all? <a class="header-anchor" href="#can-i-stop-it-from-writing-at-all" aria-label="Permalink to “Can I stop it from writing at all?”">​</a></h2><p>Two ways, and they are not equivalent:</p><ul><li><code>OPENGIST_READ_ONLY=true</code> does not register the write tools. Convenient, enforced by this server.</li><li>A token scoped to <code>gist:read</code> and <code>user:read</code> cannot write, whatever this server or the model does. That is the one that actually holds.</li></ul><p>Use the second one if it matters.</p><h2 id="which-opengist-versions-work" tabindex="-1">Which Opengist versions work? <a class="header-anchor" href="#which-opengist-versions-work" aria-label="Permalink to “Which Opengist versions work?”">​</a></h2><p>Any release with the REST API enabled (<code>api.enabled</code>, on by default in recent versions). A running instance serves its own spec at <code>GET /api/openapi.yaml</code> — if a tool behaves unexpectedly, compare that against your version first.</p>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};